SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',false);
DO $$
DECLARE c uuid:='10000000-0000-4000-8000-000000000001'; o jsonb; payload jsonb; receipt jsonb; again jsonb; req uuid; rev uuid; line_id uuid; n integer;
BEGIN
 payload:=jsonb_build_object('requestId',gen_random_uuid(),'contactId','30000000-0000-4000-8000-000000000001','orderDate','2026-11-18','currencyCode','GBP','lines',jsonb_build_array(jsonb_build_object('description','Approval item','accountId','20000000-0000-4000-8000-000000000001','quantity',3,'unitPriceMinor',100,'discountMinor',1,'taxRateBps',2000)));
 o:=public.save_purchase_order_atomic(c,payload);
 PERFORM public.po_test_error(format('SELECT public.manage_purchase_order(%L,%L,1,%L)',c,o->>'id','send'),'%Approve this order%','PO cannot send without approval');
 PERFORM public.po_test_error(format('SELECT public.change_purchase_order_atomic(%L,%L,%L)',c,o->>'id','sent'),'%Reload%','legacy status endpoint cannot bypass approval');
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,1,'submit');
 PERFORM public.po_test_assert(o->>'approval_state'='pending' AND (o->>'version')::int=2,'PO submission changes approval state/version');
 PERFORM public.po_test_error(format('SELECT public.manage_purchase_order(%L,%L,1,%L)',c,o->>'id','reset'),'%reload%','PO stale version rejected');
 PERFORM public.po_test_error(format('SELECT public.manage_purchase_order(%L,%L,2,%L)',c,o->>'id','approve'),'%different authorised user%','PO maker cannot self approve');
 PERFORM public.po_test_error(format('SELECT public.save_purchase_order_atomic(%L,%L)',c,(payload||jsonb_build_object('orderId',o->>'id','version',2,'memo','Unreviewed change'))::text),'%Withdraw%','pending PO commercial edits rejected');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003"}',true);
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,2,'reject','{"comment":"Change specification"}');
 PERFORM public.po_test_assert(o->>'approval_state'='rejected','PO rejection recorded');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',true);
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,3,'reset');
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,4,'submit');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003"}',true);
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,5,'approve');
 PERFORM public.po_test_assert(EXISTS(SELECT 1 FROM public.purchase_orders WHERE id=(o->>'id')::uuid AND approved_by='00000000-0000-4000-8000-000000000003'),'PO independent approval actor persisted');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',true);
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,6,'metadata','{"supplierReference":"SUP-REF","expectedDeliveryDate":"2026-11-18","acknowledgedOn":"2026-11-18","deliveryAddress":"Receiving dock","terms":"Agreed terms"}');
 -- Commercial terms changed after approval, requiring a fresh decision.
 PERFORM public.po_test_assert(o->>'approval_state'='draft','commercial term edit invalidates approval');
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,7,'submit');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003"}',true);
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,8,'approve');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',true);
 o:=public.manage_purchase_order(c,(o->>'id')::uuid,9,'send');
 PERFORM public.po_test_assert(o->>'status'='sent' AND (public.browse_purchase_orders(c,'SUP-REF','sent')->>'total')::int=1,'approved PO sends and supplier reference is searchable');
 SELECT id INTO line_id FROM public.purchase_order_lines WHERE order_id=(o->>'id')::uuid;
 PERFORM public.po_test_error(format('SELECT public.receive_purchase_order_goods(%L,%L,%L)',c,o->>'id','{"lines":[]}'),'%Reload%','legacy receipt endpoint cannot bypass receipt identity');
 req:=gen_random_uuid();
 receipt:=public.receive_purchase_order(c,(o->>'id')::uuid,req,'2026-11-18','GR-1',jsonb_build_array(jsonb_build_object('lineId',line_id,'receiveQuantity',1)));
 again:=public.receive_purchase_order(c,(o->>'id')::uuid,req,'2026-11-18','GR-1',jsonb_build_array(jsonb_build_object('lineId',line_id,'receiveQuantity',1)));
 PERFORM public.po_test_assert(receipt->>'receiptId'=again->>'receiptId' AND (SELECT quantity_received FROM public.purchase_order_lines WHERE id=line_id)=1,'receipt retry is idempotent');
 PERFORM public.po_test_error(format('SELECT public.receive_purchase_order(%L,%L,%L,%L,%L,%L)',c,o->>'id',req,'2026-11-18','GR-1',jsonb_build_array(jsonb_build_object('lineId',line_id,'receiveQuantity',2))::text),'%different data%','receipt request cannot change payload');
 PERFORM public.po_test_error(format('SELECT public.receive_purchase_order(%L,%L,%L,%L,%L,%L)',c,o->>'id',gen_random_uuid(),'2026-11-18','GR-over',jsonb_build_array(jsonb_build_object('lineId',line_id,'receiveQuantity',3))::text),'%outstanding quantity%','over receipt rejected');
 PERFORM public.po_test_error(format('SELECT public.manage_purchase_order(%L,%L,%s,%L,%L)',c,o->>'id',receipt->>'version','cancel','{"comment":"Cancel remaining"}'),'%Reverse receipts%','received PO cannot cancel silently');
 rev:=gen_random_uuid();
 receipt:=public.reverse_purchase_receipt(c,(o->>'id')::uuid,(receipt->>'receiptId')::uuid,rev,'Received damaged goods');
 again:=public.reverse_purchase_receipt(c,(o->>'id')::uuid,(receipt->>'receiptId')::uuid,rev,'Received damaged goods');
 PERFORM public.po_test_assert(receipt->>'receiptId'=again->>'receiptId' AND (SELECT quantity_received FROM public.purchase_order_lines WHERE id=line_id)=0,'receipt reversal and retry restore quantities once');
 PERFORM public.po_test_assert(jsonb_array_length(public.get_purchase_order_activity(c,(o->>'id')::uuid)->'history')>=10,'PO history exposes real workflow events');
 SELECT count(*) INTO n FROM public.purchase_order_receipts;
 PERFORM set_config('test.fail_audit','on',true);
 PERFORM public.po_test_error(format('SELECT public.receive_purchase_order(%L,%L,%L,%L,%L,%L)',c,o->>'id',gen_random_uuid(),'2026-11-18','GR-rollback',jsonb_build_array(jsonb_build_object('lineId',line_id,'receiveQuantity',1))::text),'%Injected audit failure%','receipt audit failure surfaced');
 PERFORM set_config('test.fail_audit','off',true);
 PERFORM public.po_test_assert((SELECT count(*) FROM public.purchase_order_receipts)=n AND (SELECT quantity_received FROM public.purchase_order_lines WHERE id=line_id)=0,'receipt audit failure rolls back document and counter');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004"}',true);
 PERFORM public.po_test_error(format('SELECT public.manage_purchase_order(%L,%L,%s,%L)',c,o->>'id',receipt->>'version','submit'),'%access denied%','view-only PO mutation denied');
 PERFORM set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002"}',true);
 PERFORM public.po_test_assert(NOT EXISTS(SELECT 1 FROM public.purchase_order_receipts) AND NOT EXISTS(SELECT 1 FROM public.purchase_order_events),'receipt/event RLS hides other tenant');
 PERFORM public.po_test_error(format('SELECT public.get_purchase_order_activity(%L,%L)',c,o->>'id'),'%access denied%','cross-tenant PO activity denied');
END $$;
RESET ROLE;
SELECT public.po_test_assert(NOT has_table_privilege('authenticated','public.purchase_order_receipts','INSERT'),'direct receipt writes denied');
SELECT public.po_test_assert(NOT has_function_privilege('anon','public.manage_purchase_order(uuid,uuid,bigint,text,jsonb)','EXECUTE'),'anonymous PO controls denied');
SELECT public.po_test_assert((SELECT count(*) FROM public.journals)=0,'PO operational lifecycle does not post journals');
